BEGIN;
CREATE TABLE IF NOT EXISTS public.site_faq (
  id text PRIMARY KEY DEFAULT 'main' CHECK (id = 'main'),
  questions jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(questions) = 'array' AND jsonb_array_length(questions) <= 30),
  benefits jsonb NOT NULL DEFAULT '[]'::jsonb CHECK (jsonb_typeof(benefits) = 'array' AND jsonb_array_length(benefits) <= 12),
  media_cleanup_paths jsonb NOT NULL DEFAULT '[]'::jsonb,
  revision bigint NOT NULL DEFAULT 1 CHECK (revision > 0),
  updated_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.site_faq ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.site_faq FROM anon, authenticated;
GRANT SELECT ON public.site_faq TO anon, authenticated;
GRANT ALL ON public.site_faq TO service_role;
DROP POLICY IF EXISTS "FAQ is public" ON public.site_faq;
CREATE POLICY "FAQ is public" ON public.site_faq FOR SELECT TO anon, authenticated USING (true);
INSERT INTO public.site_faq (id, questions, benefits) VALUES ('main', '[{"id":"systems","question":"Какие типы систем вы обслуживаете?","answer":"Обслуживаем инженерные системы зданий, индивидуальные тепловые пункты и узлы учёта тепловой энергии. Состав работ уточняем после знакомства с объектом."},{"id":"emergency","question":"Как быстро вы можете реагировать на аварии?","answer":"Порядок и время аварийного реагирования согласовываем индивидуально и закрепляем в договоре обслуживания."},{"id":"warranty","question":"Предоставляете ли вы гарантию на свою работу?","answer":"Гарантийные условия зависят от вида работ и фиксируются в договоре. Обсудим их при подготовке предложения."},{"id":"region","question":"Можете ли вы обслуживать объекты за пределами города?","answer":"Возможность обслуживания зависит от расположения объекта и состава работ. Свяжитесь с нами, чтобы обсудить ваш объект."},{"id":"certificates","question":"Какие сертификаты имеют ваши специалисты?","answer":"Документы и допуски для конкретных работ предоставим по запросу. Информация также доступна в разделе «Лицензии и сертификаты»."}]'::jsonb, '[{"id":"quality","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" color=\"#ffffff\"><g fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"><path d=\"M20 13c0 5-3.5 7.5-7.66 8.95a1 1 0 0 1-.67-.01C7.5 20.5 4 18 4 13V6a1 1 0 0 1 1-1c2 0 4.5-1.2 6.24-2.72a1.17 1.17 0 0 1 1.52 0C14.51 3.81 17 5 19 5a1 1 0 0 1 1 1z\"/><path d=\"m9 12l2 2l4-4\"/></g></svg>","iconFilename":"quality.svg","iconPath":null,"title":"Гарантия качества","text":"Применяются высочайшие отраслевые стандарты"},{"id":"speed","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" color=\"#ffffff\"><g fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 6v6l4 2\"/></g></svg>","iconFilename":"speed.svg","iconPath":null,"title":"Работа в краткие сроки","text":"Соблюдение графиков и сроков"},{"id":"experience","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"24\" height=\"24\" viewBox=\"0 0 24 24\" color=\"#ffffff\"><path fill=\"none\" stroke=\"currentColor\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M11.525 2.295a.53.53 0 0 1 .95 0l2.31 4.679a2.12 2.12 0 0 0 1.595 1.16l5.166.756a.53.53 0 0 1 .294.904l-3.736 3.638a2.12 2.12 0 0 0-.611 1.878l.882 5.14a.53.53 0 0 1-.771.56l-4.618-2.428a2.12 2.12 0 0 0-1.973 0L6.396 21.01a.53.53 0 0 1-.77-.56l.881-5.139a2.12 2.12 0 0 0-.611-1.879L2.16 9.795a.53.53 0 0 1 .294-.906l5.165-.755a2.12 2.12 0 0 0 1.597-1.16z\"/></svg>","iconFilename":"experience.svg","iconPath":null,"title":"Проверенный опыт","text":"Успешный опыт более 100 проектов"}]'::jsonb) ON CONFLICT (id) DO NOTHING;
NOTIFY pgrst, 'reload schema';
COMMIT;
